"""Exact no-child successor stages, using the existing Runner/Inputs recipe."""
from pathlib import Path
import gzip,hashlib,importlib.util,json,sys
sys.dont_write_bytecode=True
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[7]
def load(name,path):
 s=importlib.util.spec_from_file_location(name,path);m=importlib.util.module_from_spec(s);s.loader.exec_module(m);return m
def sha(path):
 if path.is_symlink() or not path.is_file():raise ValueError('regular nonsymlink input required')
 return hashlib.sha256(path.read_bytes()).hexdigest()
def main(directory):
 out=Path(directory).resolve()
 assert not out.exists() and not out.is_symlink()
 P=load('preparation',HERE/'prepare.py');C=load('config',ROOT/'experiments/public-simulation/delivery-v1/installed-config.py');T=load('runner',ROOT/'scripts/task_runner.py');F=load('force',HERE.parents[3]/'trace-cheap.py')
 controls=load('controls',HERE.parent/'direct-source-controls.py');controls.main()
 files=set();P.closure(HERE/'driver-direct.bend',files);P.closure(HERE.parent/'direct-fuel-controls.bend',files)
 inventory={str(p):sha(p) for p in sorted(files)}
 tools={**C.TOOL_PATHS,'bend':'/home/node/.bend/bin/bend-2.0.35','python':str(Path('/usr/bin/python3.11').resolve(strict=True))}
 assert sha(Path(tools['bend']))=='f77417474ded314ad5d1a68fa3ebbe214c2124bf04d56a59b05bc17be6b0327a'
 files.update(Path(v).resolve(strict=True) for v in tools.values())
 files.update([Path(__file__).resolve(),HERE/'next-state-execution.py',HERE/'test-next-state-entry-preimport.py',HERE/'test-next-state-failure.py',HERE/'test-failure-guard-control.py',HERE/'prepare.py',HERE.parent/'direct-source-controls.py',HERE/'driver.bend',HERE.parent/'serialize.bend',HERE.parent/'direct-fuel-controls.expected',ROOT/'scripts/task_runner.py',ROOT/'scripts/receipt-logs.py',ROOT/'scripts/evidence_boundary.py',ROOT/'experiments/public-simulation/delivery-v1/installed-config.py',HERE.parents[3]/'trace-cheap.py',HERE/'prepared/manifest.json'])
 cases=[];manifest=json.loads((HERE/'prepared/manifest.json').read_text());assert len(manifest['cases'])==9
 for c in manifest['cases']:
  path=HERE/'prepared'/c['oracle'];files.add(path);raw=gzip.decompress(path.read_bytes());assert len(raw)==c['bytes'] and hashlib.sha256(raw).hexdigest()==c['sha256'];cases.append({**c,'oracle':str(path),'walk':F.force(json.loads(raw))})
 pins={str(p):sha(p) for p in sorted(files)}
 resources=T.Inputs(directories=C.RESOURCE_ROOTS).expected
 common=dict(subject='serializer-next-state',executionPython=tools['python'],executionSource=str(HERE/'next-state-execution.py'),pins=pins,sourceInventory=inventory,resourceRoots=resources,environment=C.environment(),cwd=str(ROOT),lock='/tmp/bendvy-parity-heavy.lock',status='NOT_LAUNCH_ADMITTED',scope='Direct fuel/pending/chunks serializer; full unchanged feature semantics; no comparative timing or task closure')
 out.mkdir();prefix=[tools['taskset'],'-c','5'];entry=str(HERE/'driver-direct.bend');plans={}
 for label,source,suffix in [('fuel-js',HERE.parent/'direct-fuel-controls.bend','js'),('full-js',Path(entry),'js'),('full-native',Path(entry),'c')]:
  directory=out/label;artifact=directory/('trace.'+suffix)
  plan={**common,'stage':'emit','output':str(directory),'generated':[str(artifact)],'commands':[dict(label='emit',argv=prefix+[tools['bend'],str(source),'-o',str(artifact)],seconds=30)],'allNineOracles':cases}
  path=out/(label+'-emit-plan.json');path.write_text(json.dumps(plan,indent=2)+'\n');plans[path.name]=sha(path)
 # All follow-up code is pinned above; generated bytes must be reviewed and frozen
 # before these exact recipes are instantiated, never guessed by this preparation.
 sequence=dict(status='ARTIFACT_DEPENDENT_UNADMITTED',executionSource=str(HERE/'next-state-execution.py'),executionSourceSHA256=sha(HERE/'next-state-execution.py'),cases=cases,stages=[dict(stage='fuel-runtime',backend='js',seconds=5,oracle=str(HERE.parent/'direct-fuel-controls.expected'),depends='reviewed fuel-js artifact SHA'),dict(stage='runtime',backend='js',seconds=5,cases=9,depends='reviewed full-js artifact SHA and forcing/source inspection'),dict(stage='build',backend='native',seconds=120,argv=prefix+[tools['clangWrapper'],'-O3','REVIEWED_C','-o','ABSENT_BINARY','-pthread','-lm'],depends='reviewed full-native C SHA/whole source closure'),dict(stage='runtime',backend='native',seconds=5,cases=9,argvSuffix=['--threads','1','--gpu','off'],depends='reviewed exact built binary SHA'),dict(stage='cpu-profile',backend='js',seconds=5,input=['depth','256','16','0'],sampler='existing Inspector100us and Heap1MiB wrappers, reviewed artifact binding required',depends='reviewed full-js semantics+profile artifact paths',before='retained matched depth256/span16 profile only; no baseline replay',allocation='Separate existing sampled allocation instrumentation if admitted; CPU samples alone are not allocations')],noJS1024ScopeCut=True,noUnchangedReplay=True,profileCensorship='Builtin CPU profile normally flushes on process exit; deadline may retain no profile. Failure and any partial artifact are retained, never interpreted as successful qualification.')
 path=out/'sequence.json';path.write_text(json.dumps(sequence,indent=2)+'\n');plans[path.name]=sha(path)
 print(json.dumps(plans,indent=2))
if __name__=='__main__':main(sys.argv[1])
